    if(!grant.tools.length||grant.tools.length>50||new Set(grant.tools).size!==grant.tools.length)throw new Error('Select one or more unique tools for this production.');
    const selected=grant.tools.map(name=>{const matches=session.connection.tools.filter(tool=>tool.name===name);if(matches.length!==1)throw new Error('An allowed tool is no longer uniquely available on the selected server.');return matches[0]});
